  <table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 0 16px;">
    <tr>
      <td style="border-radius:9px;background:#0d9488;">
        <a href="https://hris.asiaraya.co.id/me/leave" style="display:inline-block;padding:11px 22px;font-size:12.8px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:9px;">Ajukan Cuti</a>
      </td>
    </tr>
  </table>
  <p style="margin:0 0 14px;font-size:10.8px;line-height:1.6;color:#7d8ea1;word-break:break-all;">
